entries[10650] = { ["name"] = "Drachenschuppenbrustplatte", ["text"] = "Wirken in 45 sek.\nReagenzien:\nDickes Leder (40), Abgenutzte Drachenschuppe (30), Schwerer Seidenfaden (4), Geschmeidiger dicker Balg (4)\nDrachenschuppenbrustplatte\nWird beim Anlegen gebunden\nBrust Kette\n306 Rüstung\n+10 Ausdauer\n+13 Feuerwiderstand\n+13 Frostwiderstand\n+12 Schattenwiderstand\nHaltbarkeit 120 / 120\n46\nBenutzen: Absorbiert 600 Magieschaden. Hält 2 Min. lang an. (1 Stunde Abklingzeit)" }
